//! 🧵️ Original immutable snapshots lend bounded tree probes and pixel pages under caller grants.
use super::*;
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,ValueError,ValueRefusalKind,retained_clone::RetainedCloneClose,work::RetainedWorkLedger};
use std::mem::ManuallyDrop;
use semio_framework_pixels::retirement::RasterLease;

#[derive(semio_framework_value::RetireOwned)]
struct Data {layers:Vec<RasterStackLayer>,images:Vec<(String,RasterLease)>,current:Option<RasterStackLayer>,image:Option<RasterImage>,lease:Option<RasterLease>,scratch:String,at:[usize;33],out_at:[usize;33],locks:[bool;33],depth:usize,base:usize,end:usize,nodes:usize,phase:u8,key_slot:usize,candidate:usize,offset:usize,asset:usize}
impl Default for Data {fn default()->Self{Self{layers:Vec::new(),images:Vec::new(),current:None,image:None,lease:None,scratch:String::new(),at:[0;33],out_at:[0;33],locks:[false;33],depth:0,base:0,end:0,nodes:0,phase:0,key_slot:0,candidate:0,offset:0,asset:0}}}

/// 🔒️ The caller retains this exact immutable snapshot until preparation has transferred or closed.
pub struct RasterStackPreparation {document:usize,wanted:usize,length:usize,edit:bool,data:ManuallyDrop<Option<Data>>,retirement:RetainedCloneClose,pending:RetirementDemand,closing:bool,failed:bool}
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn source<'a>(document:&'a RasterSnapshot,data:&Data)->Result<(&'a[RasterLayerNode],&'a RasterLayerNode),ValueError>{let mut layers=document.layers.as_slice();for depth in 0..data.depth{let Some(RasterLayerNode::Group{children,..})=layers.get(data.at[depth])else{return Err(refusal("raster.stack-source-path-changed"))};layers=children;}Ok((layers,layers.get(data.at[data.depth]).ok_or_else(||refusal("raster.stack-source-path-changed"))?))}
fn source_layers<'a>(document:&'a RasterSnapshot,data:&Data)->Result<&'a[RasterLayerNode],ValueError>{let mut layers=document.layers.as_slice();for depth in 0..data.depth{let Some(RasterLayerNode::Group{children,..})=layers.get(data.at[depth])else{return Err(refusal("raster.stack-source-path-changed"))};layers=children;}Ok(layers)}
fn output(data:&mut Data)->Result<&mut Vec<RasterStackLayer>,ValueError>{let mut layers=&mut data.layers;for depth in 0..data.depth-data.base{let Some(RasterStackLayer{content:RasterStackContent::Group(children),..})=layers.get_mut(data.out_at[depth])else{return Err(refusal("raster.stack-output-path-changed"))};layers=children;}Ok(layers)}
fn locked(layer:&RasterLayerNode)->bool{match layer{RasterLayerNode::Pixel{locked,..}|RasterLayerNode::Group{locked,..}|RasterLayerNode::Adjustment{locked,..}=>*locked}}
fn mask(layer:&RasterLayerNode)->Option<&semio_s_artifact_raster_raster_model::RasterLayerMask>{match layer{RasterLayerNode::Pixel{mask,..}|RasterLayerNode::Group{mask,..}=>mask.as_ref(),_=>None}}
fn key(layer:&RasterStackLayer,slot:usize)->Option<&str>{if slot==0{match &layer.content{RasterStackContent::Pixel{image_key,..}=>image_key.as_deref(),_=>None}}else{layer.mask.as_ref().filter(|mask|mask.enabled).and_then(|mask|mask.image_key.as_deref())}}
fn copy(source:&str,target:&mut String,body:usize,work:&mut RetainedWorkLedger)->Result<bool,ValueError>{if source.len()>semio_s_artifact_raster_raster_model::RASTER_OWNED_FIELD_BYTES{return Err(refusal("raster.stack-owned-field-budget"))}if !work.reserve_string(target,source.len()).map_err(refusal)?{return Ok(false)}if target.len()==source.len(){return Ok(true)}let start=target.len();let mut end=(start+body.min(32768)).min(source.len());while end>start&&!source.is_char_boundary(end){end-=1}if end==start{work.require_absolute(RetirementDemand{copy_bytes:source[start..].chars().next().unwrap().len_utf8(),depth:1,..Default::default()});return Ok(false)}if !work.string_push(target,&source[start..end]).map_err(refusal)?{return Ok(false)}Ok(end==source.len())}
fn compare(left:&str,right:&str,offset:&mut usize,body:usize,work:&mut RetainedWorkLedger)->Result<Option<bool>,ValueError>{if left.len()!=right.len(){return Ok(Some(false))}let count=(left.len()-*offset).min(body.min(32768)/2);if count==0&&*offset<left.len(){work.require_absolute(RetirementDemand{copy_bytes:2,depth:1,..Default::default()});return Ok(None)}if !work.copy_bytes(count*2){return Ok(None)}let equal=left.as_bytes()[*offset..*offset+count]==right.as_bytes()[*offset..*offset+count];*offset+=count;Ok(if !equal{Some(false)}else if *offset==left.len(){Some(true)}else{None})}

impl RasterStackPreparation {
    pub fn new(document:&RasterSnapshot)->Result<Self,ValueError>{Self::from_layers(document,&document.layers)}
    pub fn from_layers(document:&RasterSnapshot,layers:&[RasterLayerNode])->Result<Self,ValueError>{Self::capture(document,layers,false)}
    pub fn for_edit(document:&RasterSnapshot,layers:&[RasterLayerNode])->Result<Self,ValueError>{Self::capture(document,layers,true)}
    fn capture(document:&RasterSnapshot,layers:&[RasterLayerNode],edit:bool)->Result<Self,ValueError>{if layers.len()>1024{return Err(refusal("raster.stack-layer-budget"))}let mut data=Data::default();if layers.is_empty(){data.phase=30}Ok(Self{document:document as*const _ as usize,wanted:layers.as_ptr() as usize,length:layers.len(),edit,data:ManuallyDrop::new(Some(data)),retirement:Default::default(),pending:RetirementDemand{depth:1,..Default::default()},closing:false,failed:false})}
    pub fn demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if body==0||body>32768{return Err(refusal("raster.stack-copy-budget"))}if self.closing||self.failed{return Err(refusal("raster.stack-preparation-inactive"))}Ok(self.pending)}
    pub fn output_ready(&self)->bool{!self.closing&&!self.failed&&self.data.as_ref().is_some_and(|data|data.phase==30)}
    fn selected(&mut self,document:&RasterSnapshot,body:usize,work:&mut RetainedWorkLedger)->Result<(),ValueError>{
        if self.document!=document as*const _ as usize{return Err(refusal("raster.stack-source-revision-changed"))}let data=self.data.as_mut().ok_or_else(||refusal("raster.stack-preparation-transferred"))?;
        match data.phase {
            0=>{let layers=source_layers(document,data)?;if data.at[data.depth]>=layers.len(){if data.depth==0{return Err(refusal("raster.stack-source-range-unavailable"))}data.depth-=1;data.at[data.depth]+=1;return Ok(())}data.nodes+=1;if data.nodes>4096{return Err(refusal("raster.stack-discovery-budget"))}let layer=&layers[data.at[data.depth]];if layer as*const _ as usize==self.wanted{if data.at[data.depth]+self.length>layers.len(){return Err(refusal("raster.stack-source-range-unavailable"))}data.base=data.depth;data.end=data.at[data.depth]+self.length;data.nodes=0;data.phase=if self.edit{19}else{1};}else if let RasterLayerNode::Group{children,..}=layer{if !children.is_empty(){if data.depth==32{return Err(refusal("raster.stack-depth-budget"))}data.locks[data.depth+1]=data.locks[data.depth]||locked(layer);data.depth+=1;data.at[data.depth]=0;}else{data.at[data.depth]+=1;}}else{data.at[data.depth]+=1;}},
            1=>{if work.contiguous(&mut data.layers,self.length).map_err(refusal)?{data.phase=2;}},
            2=>{if work.contiguous(&mut data.images,64).map_err(refusal)?{data.phase=3;}},
            3=>{
                if data.at[data.depth]>=source_layers(document,data)?.len()||data.depth==data.base&&data.at[data.depth]>=data.end{data.phase=18;return Ok(())}let (_,layer)=source(document,data)?;data.nodes+=1;if data.nodes>1024{return Err(refusal("raster.stack-layer-budget"))}if self.edit&&(data.locks[data.depth]||locked(layer)){return Err(refusal("raster-layer-locked"))}let maximum=semio_s_artifact_raster_raster_model::RASTER_OWNED_FIELD_BYTES;if layer_node_id(layer).len()>maximum||mask(layer).and_then(|mask|mask.image_key.as_ref()).is_some_and(|key|key.len()>maximum)||matches!(layer,RasterLayerNode::Pixel{image_key:Some(key),..}if key.len()>maximum){return Err(refusal("raster.stack-owned-field-budget"))}
                let content=match layer{RasterLayerNode::Pixel{width,height,image_key,..}=>RasterStackContent::Pixel{width:*width,height:*height,image_key:image_key.as_ref().map(|_|String::new())},RasterLayerNode::Group{children,..}=>{if children.len()>1024{return Err(refusal("raster.stack-layer-budget"))}RasterStackContent::Group(Vec::new())},RasterLayerNode::Adjustment{adjustment_kind,params,..}=>{if adjustment_kind!="brightnessContrast"{return Err(refusal("raster.stack-adjustment-unsupported"))}let parameter=|name:&str|params.get(name).map_or(Ok(0.0),|value|value.as_f64().ok_or_else(||refusal("raster.stack-adjustment-invalid")));RasterStackContent::BrightnessContrast{brightness:parameter("brightness")?,contrast:parameter("contrast")?}}};
                let layer_mask=mask(layer).map(|mask|RasterStackMask{enabled:mask.enabled,linked:mask.linked,invert:mask.invert,width:mask.width,height:mask.height,image_key:mask.image_key.as_ref().map(|_|String::new()),transform:stack_transform(&mask.transform)});
                data.current=Some(RasterStackLayer{id:String::new(),visible:layer_visible(layer),opacity:f64::from(semio_s_artifact_raster_raster_model::layer_opacity(layer)),blend_mode:semio_s_artifact_raster_raster_model::layer_blend_mode(layer).parse().map_err(|_|refusal("raster.stack-blend-unsupported"))?,transform:stack_transform(semio_s_artifact_raster_raster_model::layer_transform(layer)),mask:layer_mask,content});data.phase=4;
            },
            4=>{let (_,layer)=source(document,data)?;if copy(layer_node_id(layer),&mut data.current.as_mut().unwrap().id,body,work)?{data.phase=5;}},
            5=>{let (_,layer)=source(document,data)?;if let RasterLayerNode::Pixel{image_key:Some(source),..}=layer{let RasterStackContent::Pixel{image_key:Some(target),..}=&mut data.current.as_mut().unwrap().content else{return Err(refusal("raster.stack-pixel-key-slot"))};if !copy(source,target,body,work)?{return Ok(())}}data.phase=6;},
            6=>{let (_,layer)=source(document,data)?;if let Some(source)=mask(layer).and_then(|mask|mask.image_key.as_ref()){let target=data.current.as_mut().unwrap().mask.as_mut().unwrap().image_key.as_mut().unwrap();if !copy(source,target,body,work)?{return Ok(())}}data.phase=7;},
            7=>{let (_,layer)=source(document,data)?;if let RasterLayerNode::Group{children,..}=layer{let RasterStackContent::Group(target)=&mut data.current.as_mut().unwrap().content else{return Err(refusal("raster.stack-group-slot"))};if !work.contiguous(target,children.len()).map_err(refusal)?{return Ok(())}}data.key_slot=0;data.phase=8;},
            8=>{if data.key_slot>=2{data.phase=17;}else if key(data.current.as_ref().unwrap(),data.key_slot).is_some(){data.candidate=0;data.offset=0;data.phase=9;}else{data.key_slot+=1;}},
            9=>{if let Some((candidate,_))=data.images.get(data.candidate){let source=key(data.current.as_ref().unwrap(),data.key_slot).unwrap();if let Some(equal)=compare(source,candidate,&mut data.offset,body,work)?{data.offset=0;if equal{data.key_slot+=1;data.phase=8;}else{data.candidate+=1;}}}else{if data.images.len()==64{return Err(refusal("raster.stack-asset-budget"))}data.phase=10;}},
            10=>{let source=key(data.current.as_ref().unwrap(),data.key_slot).unwrap();if copy(source,&mut data.scratch,body,work)?{data.candidate=0;data.offset=0;data.phase=11;}},
            11=>{let Some((candidate,_))=document.assets.iter().nth(data.candidate)else{return Err(refusal("raster.stack-asset-missing"))};if let Some(equal)=compare(&data.scratch,candidate,&mut data.offset,body,work)?{data.offset=0;if equal{data.asset=data.candidate;data.phase=12;}else{data.candidate+=1;}}},
            12=>{let (_,child)=document.assets.iter().nth(data.asset).ok_or_else(||refusal("raster.stack-source-asset-changed"))?;let image=child.local_owner::<SemioImageSnapshot>().ok_or_else(||refusal("raster.stack-image-unavailable"))?;let count=validate_extent(image.width,image.height).map_err(|_|refusal("raster.stack-image-extent"))?;if image.frames.first().is_none_or(|frame|frame.rgba8.len()!=count*4){return Err(refusal("raster.stack-image-frame"))}data.image=Some(RasterImage{width:image.width,height:image.height,pixels:Vec::new()});data.phase=13;},
            13=>{let image=data.image.as_mut().unwrap();let count=image.width as usize*image.height as usize*4;if work.contiguous(&mut image.pixels,count).map_err(refusal)?{data.phase=14;}},
            14=>{let (_,child)=document.assets.iter().nth(data.asset).ok_or_else(||refusal("raster.stack-source-asset-changed"))?;let source=child.local_owner::<SemioImageSnapshot>().ok_or_else(||refusal("raster.stack-image-unavailable"))?;let target=data.image.as_mut().unwrap();let total=target.width as usize*target.height as usize*4;if source.width!=target.width||source.height!=target.height||source.frames.first().is_none_or(|frame|frame.rgba8.len()!=total){return Err(refusal("raster.stack-source-image-changed"))}let start=target.pixels.len();let count=(total-start).min(body.min(32768));if !work.copy_bytes(count){return Ok(())}target.pixels.extend_from_slice(&source.frames[0].rgba8[start..start+count]);if target.pixels.len()==total{data.phase=15;}},
            15=>{if !work.arc_ready::<RasterImage>().map_err(refusal)?{return Ok(())}let image=data.image.take().unwrap();match work.arc_new(image){Ok(image)=>{data.lease=Some(RasterLease(image));data.phase=16;},Err((error,image))=>{data.image=Some(image);return Err(refusal(error));}}},
            16=>{if !work.vec_slot(&mut data.images).map_err(refusal)?{return Ok(())}let row=(std::mem::take(&mut data.scratch),data.lease.take().unwrap());if let Err((error,row))=work.vec_push(&mut data.images,row){data.scratch=row.0;data.lease=Some(row.1);return Err(refusal(error))}data.key_slot+=1;data.phase=8;},
            17=>{let (_,layer)=source(document,data)?;let child_count=match layer{RasterLayerNode::Group{children,..}=>children.len(),_=>0};let inherited=data.locks[data.depth]||locked(layer);let current=data.current.take().unwrap();let destination=output(data)?;if !work.vec_slot(destination).map_err(refusal)?{data.current=Some(current);return Ok(())}let index=destination.len();if let Err((error,current))=work.vec_push(destination,current){data.current=Some(current);return Err(refusal(error))}if child_count>0{if data.depth==32{return Err(refusal("raster.stack-depth-budget"))}data.out_at[data.depth-data.base]=index;data.locks[data.depth+1]=inherited;data.depth+=1;data.at[data.depth]=0;}else{data.at[data.depth]+=1;}data.phase=18;},
            18=>{let done=if data.depth==data.base{data.at[data.depth]>=data.end}else{data.at[data.depth]>=source_layers(document,data)?.len()};if done{if data.depth==data.base{data.phase=30;}else{data.depth-=1;data.at[data.depth]+=1;}}else{data.phase=3;}},
            19=>{let layers=source_layers(document,data)?;let done=if data.depth==data.base{data.at[data.depth]>=data.end}else{data.at[data.depth]>=layers.len()};if done{if data.depth==data.base{data.at[data.depth]=data.end-self.length;data.nodes=0;data.phase=1;}else{data.depth-=1;data.at[data.depth]+=1;}return Ok(())}let layer=&layers[data.at[data.depth]];data.nodes+=1;if data.nodes>1024{return Err(refusal("raster.stack-layer-budget"))}if data.locks[data.depth]||locked(layer){return Err(refusal("raster-layer-locked"))}if let RasterLayerNode::Group{children,..}=layer{if !children.is_empty(){if data.depth==32{return Err(refusal("raster.stack-depth-budget"))}data.locks[data.depth+1]=data.locks[data.depth]||locked(layer);data.depth+=1;data.at[data.depth]=0;}else{data.at[data.depth]+=1;}}else{data.at[data.depth]+=1;}},
            30=>{},_=>return Err(refusal("raster.stack-preparation-phase")),
        }Ok(())
    }
    pub fn advance(&mut self,document:&RasterSnapshot,body:usize,grant:RetainedCloneGrant)->RetainedWorkOutcome{
        if grant.maximum_items==0{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}let demand=match self.demands(body){Ok(demand)=>demand,Err(error)=>return RetainedWorkOutcome{result:Err(error),work:0}};if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,demand){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}
        let mut work=RetainedWorkLedger::new(grant);let result=self.selected(document,body,&mut work);if !work.blocked()&&work.receipt()==RetainedCloneProgress::default(){work.copy_bytes(0);}self.pending=work.next_demand();let progress=work.receipt();let cpu=work.actual_work()+1;let result=match result{Ok(())=>Ok(if self.output_ready(){RetainedCloneStep::Complete(progress)}else{RetainedCloneStep::Progress(progress)}),Err(error)=>{self.failed=true;Err(error.with_retained_progress(progress))}};RetainedWorkOutcome{result,work:cpu}
    }
    pub fn take_input(&mut self,grant:RetainedCloneGrant)->RetainedWorkOutcome<Option<(RasterStackInput,RetainedCloneProgress)>>{if !self.output_ready(){return RetainedWorkOutcome{result:Err(refusal("raster.stack-output-unavailable")),work:0}}let demand=RetirementDemand{depth:1,..Default::default()};if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,demand){return RetainedWorkOutcome{result:Ok(None),work:0}}let data=self.data.as_mut().unwrap();data.phase=31;let input=RasterStackInput{layers:std::mem::take(&mut data.layers),images:std::mem::take(&mut data.images)};RetainedWorkOutcome{result:Ok(Some((input,RetainedCloneProgress{copied_items:1,..Default::default()}))),work:1}}
    pub fn cancel(&mut self){self.closing=true;}
    pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{self.retirement.next_owner_demands::<Data>(self.data.is_some(),&None,body)}
    pub fn close_step(&mut self,grant:RetainedCloneGrant)->RetainedWorkOutcome{if !self.closing{return RetainedWorkOutcome{result:Err(refusal("raster.stack-close-intent")),work:0}}if !self.retirement.is_empty(){return self.retirement.step_granted(grant)}let turn=self.retirement.begin_granted(&mut self.data,grant);RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Complete(Default::default()))),work:turn.work}}
    pub fn terminal_is_empty(&self)->bool{self.data.is_none()&&self.retirement.is_empty()}
}
impl Drop for RasterStackPreparation{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"stack preparation retains original private nodes and pixels until funded close");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.data)}}}}

